return [
  { json: { candidate_id: 'cand-001', name: '@founder_alex', text: 'We rebuilt our dev workflow around coding agents and cut review time by half.' } },
  { json: { candidate_id: 'cand-002', name: '@devrel_mina', text: 'Trying five AI code review tools this week. Most still miss architecture context.' } },
  { json: { candidate_id: 'cand-003', name: '@research_jo', text: 'New benchmark for autonomous software agents is live.' } }
];

const scoring = {
  'cand-001': { score: 0.91, signals: ['founder role','explicit coding-agent use','recent activity'] },
  'cand-002': { score: 0.78, signals: ['developer tools','architecture pain','not clearly buyer'] },
  'cand-003': { score: 0.42, signals: ['topic match only','research orientation'] }
};
return $input.all().map(item => {
  const s = scoring[item.json.candidate_id];
  return { json: { ...item.json, relevance_score: s.score, signals: s.signals, review_required: s.score >= 0.70 } };
});

const reviews = {
  'cand-001': { decision: 'shortlist', reason: 'Strong fit: active buyer profile with explicit pain and current use.' },
  'cand-002': { decision: 'reject', reason: 'Relevant topic but role/intent are weaker for prospecting.' },
  'cand-003': { decision: 'unreviewed', reason: 'Below review threshold for this run.' }
};
return $input.all().map(item => {
  const r = reviews[item.json.candidate_id];
  return { json: { ...item.json, review_decision: r.decision, review_reason: r.reason } };
});

const candidates = $input.all().map(i => i.json);
const shortlisted = candidates
  .filter(c => c.review_decision === 'shortlist')
  .map(c => ({
    candidate_id: c.candidate_id,
    name: c.name,
    handoff_id: `handoff:${c.candidate_id}:v1`,
    handoff_status: 'prepared-local-only'
  }));
return [{ json: {
  run_id: 'fixture-run-001',
  criteria: { query: '("agentic engineering" OR "AI developer tools") lang:en', review_threshold: 0.70 },
  candidates,
  shortlisted,
  assertions: {
    collection_executed: true,
    scoring_executed: true,
    human_review_simulated_from_frozen_fixture: true,
    production_crm_write: false,
    outbound_message_sent: false
  },
  nonclaims: [
    'fixture collection does not prove X API reliability or coverage',
    'fixture scores do not prove predictive validity or conversion lift',
    'shortlist decision does not prove commercial value'
  ]
} }];
